  pdf_text_layer: ['Text taken from the PDF itself (no photo reading needed).', 'Text direkt aus dem PDF übernommen (keine Texterkennung nötig).', 'Texte repris directement du PDF (pas de lecture de photo).', 'Texto tomado directamente del PDF (sin leer una foto).', 'Testo preso direttamente dal PDF (nessuna lettura da foto).', 'Texto retirado diretamente do PDF (sem leitura de foto).'],
  pdf_truncated: ['Only the first {n} of {m} pages were read.', 'Nur die ersten {n} von {m} Seiten wurden gelesen.', 'Seules les {n} premières pages sur {m} ont été lues.', 'Solo se leyeron las primeras {n} de {m} páginas.', 'Sono state lette solo le prime {n} pagine su {m}.', 'Só foram lidas as primeiras {n} de {m} páginas.'],
  err_pdf: ['Could not open this PDF: {msg}', 'Dieses PDF konnte nicht geöffnet werden: {msg}', "Impossible d'ouvrir ce PDF : {msg}", 'No se pudo abrir este PDF: {msg}', 'Impossibile aprire questo PDF: {msg}', 'Não foi possível abrir este PDF: {msg}'],
  choose_file: ['Open a PDF or image', 'PDF oder Bild öffnen', 'Ouvrir un PDF ou une image', 'Abrir un PDF o una imagen', 'Apri un PDF o un’immagine', 'Abrir um PDF ou imagem'],
  lang_unreviewed: ['This translation has not been checked by a native speaker yet.', 'Diese Übersetzung wurde noch nicht von Muttersprachlern geprüft.', "Cette traduction n'a pas encore été relue par un locuteur natif.", 'Esta traducción aún no ha sido revisada por un hablante nativo.', 'Questa traduzione non è ancora stata controllata da un madrelingua.', 'Esta tradução ainda não foi revista por um falante nativo.'],
  cards_english: ['Card texts (next action, steps, reply) are in English for this language.', 'Kartentexte (nächster Schritt, Schritte, Antwort) sind für diese Sprache auf Englisch.', 'Pour cette langue, les textes de la fiche (action, étapes, réponse) sont en anglais.', 'Para este idioma, los textos de la tarjeta (acción, pasos, respuesta) están en inglés.', 'Per questa lingua i testi della scheda (azione, passi, risposta) sono in inglese.', 'Para esta língua, os textos do cartão (ação, passos, resposta) estão em inglês.'],
  pro_title: ['LetterScan Pro', 'LetterScan Pro', 'LetterScan Pro', 'LetterScan Pro', 'LetterScan Pro', 'LetterScan Pro'],
  pro_lead: ['A one-time purchase for extras. Reading documents, deadlines, reminders and saving cards stay free and unlimited.', 'Einmalkauf für Extras. Dokumente lesen, Fristen, Erinnerungen und Karten speichern bleiben kostenlos und unbegrenzt.', 'Achat unique pour des extras. La lecture des documents, les échéances, les rappels et l’enregistrement restent gratuits et illimités.', 'Compra única para extras. Leer documentos, plazos, recordatorios y guardar tarjetas siguen siendo gratis e ilimitados.', 'Acquisto unico per gli extra. Leggere documenti, scadenze, promemoria e salvare schede restano gratis e illimitati.', 'Compra única para extras. Ler documentos, prazos, lembretes e guardar cartões continuam gratuitos e ilimitados.'],
  pro_f_reminders: ['Your own reminder schedule (e.g. 7, 3 and 1 day before)', 'Eigener Erinnerungsplan (z. B. 7, 3 und 1 Tag vorher)', 'Vos propres rappels (ex. 7, 3 et 1 jour avant)', 'Sus propios recordatorios (p. ej. 7, 3 y 1 día antes)', 'Promemoria personalizzati (es. 7, 3 e 1 giorno prima)', 'Lembretes à sua medida (ex.: 7, 3 e 1 dia antes)'],
  pro_f_themes: ['Extra colour themes', 'Zusätzliche Farbthemen', 'Thèmes de couleur supplémentaires', 'Temas de color adicionales', 'Temi di colore aggiuntivi', 'Temas de cor adicionais'],
