  pro_f_bundle: ['Export all cards as one PDF', 'Alle Karten als ein PDF exportieren', 'Exporter toutes les fiches en un seul PDF', 'Exportar todas las tarjetas en un PDF', 'Esportare tutte le schede in un unico PDF', 'Exportar todos os cartões num só PDF'],
