  rem_set_custom: ['{n} reminder(s) set on this phone (your schedule, 9:00).', '{n} Erinnerung(en) auf diesem Telefon eingestellt (Ihr Plan, 9:00 Uhr).', '{n} rappel(s) programmé(s) sur ce téléphone (votre calendrier, 9 h).', '{n} recordatorio(s) programado(s) en este teléfono (su calendario, 9:00).', '{n} promemoria impostati su questo telefono (il tuo programma, 9:00).', '{n} lembrete(s) definido(s) neste telemóvel (o seu plano, 9:00).'],
